1	"use client";
2	
3	import type { PORTFOLIO_CATEGORIES } from "@/lib/constants/portfolio";
4	import styles from "./portfolio-filter.module.css";
5	
6	type Category = (typeof PORTFOLIO_CATEGORIES)[number];
7	
8	export type SortOption = "name-asc" | "name-desc";
9	
10	interface PortfolioFilterProps {
11	  categories: Category[];
12	  activeCategories: string[];
13	  search: string;
14	  sort: SortOption;
15	  filteredCount: number;
16	  totalCount: number;
17	  onCategoryToggle: (cat: string) => void;
18	  onCategoryRemove: (cat: string) => void;
19	  onClearAll: () => void;
20	  onSearchChange: (query: string) => void;
21	  onSortChange: (sort: SortOption) => void;
22	}
23	
24	export function PortfolioFilter({
25	  categories,
26	  activeCategories,
27	  search,
28	  sort,
29	  filteredCount,
30	  totalCount,
31	  onCategoryToggle,
32	  onCategoryRemove,
33	  onClearAll,
34	  onSearchChange,
35	  onSortChange,
36	}: PortfolioFilterProps) {
37	  const hasFilters = activeCategories.length > 0 || search.trim() !== "";
38	
39	  return (
40	    <aside className={styles.sidebar}>
41	      {/* Search */}
42	      <div className={styles.searchBlock}>
43	        <input
44	          type="search"
45	          placeholder="Search here..."
46	          value={search}
47	          onChange={(e) => onSearchChange(e.target.value)}
48	          className={styles.searchField}
49	          aria-label="Search projects"
50	        />
51	      </div>
52	
53	      {/* Active filter tags */}
54	      {activeCategories.length > 0 && (
55	        <div className={styles.tagsWrapper}>
56	          <p className={styles.tagsLabel}>Filtering by:</p>
57	          {activeCategories.map((cat) => {
58	            const label =
59	              categories.find((c) => c.slug === cat)?.name ?? cat;
60	            return (
61	              <div key={cat} className={styles.activeTag}>
62	                {label}
63	                <button
64	                  type="button"
65	                  className={styles.activeTagRemove}
66	                  onClick={() => onCategoryRemove(cat)}
67	                  aria-label={`Remove ${label} filter`}
68	                >
69	                  &times;
70	                </button>
71	              </div>
72	            );
73	          })}
74	        </div>
75	      )}
76	
77	      {/* Sort */}
78	      <div className={styles.sortBlock}>
79	        <select
80	          className={styles.sortSelect}
81	          value={sort}
82	          onChange={(e) => onSortChange(e.target.value as SortOption)}
83	          aria-label="Sort projects"
84	        >
85	          <option value="name-asc">Name (A/Z)</option>
86	          <option value="name-desc">Name (Z/A)</option>
87	        </select>
88	      </div>
89	
90	      {/* Results count */}
91	      <div className={styles.resultsBlock}>
92	        <p className={styles.resultsText}>
93	          Showing{" "}
94	          <span className={styles.resultsCount}>{filteredCount}</span>{" "}
95	          results
96	          <br />
97	          of <span className={styles.itemsCount}>{totalCount}</span> items.
98	        </p>
99	        {hasFilters && (
100	          <button
101	            type="button"
102	            className={styles.resetAll}
103	            onClick={onClearAll}
104	          >
105	            Reset All
106	          </button>
107	        )}
108	      </div>
109	
110	      {/* Category header */}
111	      <div className={styles.categoryHeader}>
112	        <h3 className={styles.categoryTitle}>Service Categories</h3>
113	        {activeCategories.length > 0 && (
114	          <button
115	            type="button"
116	            className={styles.clearBtn}
117	            onClick={onClearAll}
118	          >
119	            Clear
120	          </button>
121	        )}
122	      </div>
123	
124	      {/* Category checkboxes */}
125	      <div className={styles.categoryList}>
126	        {categories.map((cat) => {
127	          if (cat.slug === "all") return null;
128	
129	          if (cat.comingSoon) {
130	            return (
131	              <label key={cat.slug} className={styles.comingSoonLabel}>
132	                <input
133	                  type="checkbox"
134	                  disabled
135	                  className={styles.checkboxInput}
136	                />
137	                <span>{cat.name}</span>
138	                <span className={styles.comingSoonBadge}>Coming Soon</span>
139	              </label>
140	            );
141	          }
142	
143	          const isChecked = activeCategories.includes(cat.slug);
144	          return (
145	            <label key={cat.slug} className={styles.checkboxLabel}>
146	              <input
147	                type="checkbox"
148	                checked={isChecked}
149	                onChange={() => onCategoryToggle(cat.slug)}
150	                className={styles.checkboxInput}
151	              />
152	              <span>{cat.name}</span>
153	            </label>
154	          );
155	        })}
156	      </div>
157	    </aside>
158	  );
159	}
