61	function FooterNewsletter() {
62	  const [email, setEmail] = useState("");
63	  const [status, setStatus] = useState<"idle" | "success" | "error">("idle");
64	  const [submitting, setSubmitting] = useState(false);
65	
66	  async function handleSubmit(e: React.FormEvent<HTMLFormElement>) {
67	    e.preventDefault();
68	    if (!email) return;
69	    setSubmitting(true);
70	    try {
71	      await new Promise<void>((resolve) => setTimeout(resolve, 800));
72	      setStatus("success");
73	      setEmail("");
74	    } catch {
75	      setStatus("error");
76	    } finally {
77	      setSubmitting(false);
78	    }
79	  }
80	
81	  return (
82	    <div className={styles['footer-newsletter-card']}>
83	      <div className={styles['footer-newsletter-title']}>
84	        {/* "Join 500+ Subscribers" pill */}
85	        <div className={styles['news-subhead-out']}>
86	          <div className={styles['newsubott']}>
87	            <Image
88	              src="/images/webflow/Layer_1-57.svg"
89	              alt="sparkle icon"
90	              width={14}
91	              height={14}
92	              className={styles['icon-regular']}
93	            />
94	            <p style={{ margin: 0, textAlign: "left", fontSize: "12px", fontWeight: 700, lineHeight: 1.2, color: "#fff" }}>
95	              <strong style={{ fontWeight: 700, color: "#05bafe" }}>Join 500+ Subscribers</strong>
96	            </p>
97	          </div>
98	        </div>
99	
100	        {/* Heading */}
101	        <h2 className={styles['heading-2-news']}>
102	          Agency Growth Insights{" "}
103	          <span className={styles['gradient-span']}>
104	            <br />
105	            Delivered Monthly
106	          </span>
107	        </h2>
108	
109	        {/* Sub-text */}
110	        <p className={styles['paragraph-small-4-gray']}>
111	          Smart growth strategies, CRM playbooks, industry trends, early product
112	          updates, and member-only offers — designed for modern agencies.
113	        </p>
114	      </div>
115	
116	      {/* Form block */}
117	      <div className={styles['footer-newsletter-form-block']}>
118	        {status === "success" ? (
119	          <div className={styles['success-message']}>
120	            Thank you! Your submission has been received!
121	          </div>
122	        ) : (
123	          <form onSubmit={handleSubmit}>
124	            <div className={styles['column-tiny-2']}>
125	              <input
126	                type="email"
127	                name="Email-Footer-Newsletter"
128	                id="Email-Footer-Newsletter"
129	                placeholder="Enter your email"
130	                required
131	                value={email}
132	                onChange={(e) => setEmail(e.target.value)}
133	                className={styles['text-field-small']}
134	              />
135	              <button
136	                type="submit"
137	                disabled={submitting}
138	                className={styles['button-secondary-small']}
139	              >
140	                {submitting ? "Please wait..." : "Get Started"}
141	              </button>
142	            </div>
143	            {status === "error" && (
144	              <div className={styles['error-message']}>
145	                Oops! Something went wrong while submitting the form.
146	              </div>
147	            )}
148	          </form>
149	        )}
150	      </div>
151	
152	      {/* Privacy line */}
153	      <div className={styles['newsletter-btm-line']}>
154	        <Image
155	          src="/images/webflow/Vector-24.svg"
156	          alt="verified icon"
157	          width={14}
158	          height={14}
159	          className={styles['shield-icon']}
160	        />
161	        <p className={styles['news-btm-para']}>
162	          100% privacy guaranteed. Unsubscribe anytime.
163	        </p>
164	      </div>
165	    </div>
166	  );
167	}
